 pages<<[[:tag,p[:date]+' · '+p[:format]],[:title,p[:title]],[:h,'Por que esse post'],[:p,p[:angle]],[:h,'Materiais que já temos'],[:p,p[:files]],[:h,'Montagem proposta'],[:p,p[:sequence]],[:h,'Primeiro caminho de copy · capa'],[:p,p[:cover]],[:h,'Primeiro caminho de copy · legenda'],[:p,p[:caption].gsub('\\n',"\n")],[:h,'O que ajustar antes de publicar'],[:p,p[:notes]]]
